from pathlib import Path
import subprocess,hashlib,os,json,time
work=Path(__file__).resolve().parent
root=work.parents[1]
compilers={'base':root.parent/'perf-gc-dict/zig-out/bin/mylang','current':root.parent/'d9-performance43/.tmp-perf43/install/bin/mylang'}
env={k:v for k,v in os.environ.items() if not k.startswith('MYLANG_')}
env['TMPDIR']=str(root/'.tmp-nested/tmp')
result={}
for name,compiler in compilers.items():
 source=work/('source-'+name)
 binary=work/('lox-'+name+'.llvm.sym')
 cmd=[str(compiler),'build','main.my','--project','--mode','ReleaseFast','--backend','llvm','--llvm-opt','3','--lto','--keep-symbols','--cache-dir',str(work/('cache-'+name)),'-o',str(binary)]
 if name=='current': cmd+=['--value-semantics']
 print('BUILD',name,flush=True)
 started=time.monotonic()
 done=subprocess.run(cmd,cwd=source,env=env,capture_output=True,text=True)
 result[name]={'compiler':str(compiler),'compiler_sha256':hashlib.sha256(compiler.read_bytes()).hexdigest(),'command':cmd,'status':done.returncode,'seconds':time.monotonic()-started,'stderr':done.stderr,'source_sha256':{str(p.relative_to(source)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(source.rglob('*.my'))}}
 if done.returncode: print(done.stderr,flush=True)
 else: result[name]['binary_sha256']=hashlib.sha256(binary.read_bytes()).hexdigest()
 (work/'builds.json').write_text(json.dumps(result,indent=2)+'\n')
 if done.returncode: raise SystemExit(done.returncode)
 print(name,'PASS',flush=True)
